import copy

import pytest

from bedrock_protocol import v844, v859, v898, v1001, v2168, v2225

# generated by gophertunnel c8d4e93:
# packet.Animate{ActionType: packet.AnimateActionSwingArm, EntityRuntimeID: 300, Data: 1.5,
# SwingSource: packet.AnimateSwingSourceAttack}
SWING_ATTACK = bytes.fromhex("01ac020000c03f010661747461636b")

# generated by gophertunnel c8d4e93:
# packet.Animate{ActionType: packet.AnimateActionCriticalHit, EntityRuntimeID: 7}
WITHOUT_SWING_SOURCE = bytes.fromhex("04070000000000")

# generated by gophertunnel c8d4e93:
# packet.Animate{ActionType: 0, EntityRuntimeID: 1 << 32, SwingSource: packet.AnimateSwingSourceNone}
NONE_SWING_SOURCE = bytes.fromhex("0080808080100000000001046e6f6e65")

# generated by gophertunnel c8d4e93:
# packet.Animate{ActionType: packet.AnimateActionMagicCriticalHit, EntityRuntimeID: 1, Data: -1,
# SwingSource: packet.AnimateSwingSourceUseItem}
USE_ITEM_SWING_SOURCE = bytes.fromhex("0501000080bf01077573656974656d")

# generated by gophertunnel 312cff6:
# packet.Animate{ActionType: packet.AnimateActionSwingArm, EntityRuntimeID: 300}
V844 = bytes.fromhex("02ac02")

# generated by gophertunnel 312cff6:
# packet.Animate{ActionType: 0x80 | 1, EntityRuntimeID: 300, BoatRowingTime: 1.5}
V844_ROWING = bytes.fromhex("8202ac020000c03f")

# generated by gophertunnel 324ed88:
# packet.Animate{ActionType: packet.AnimateActionSwingArm, EntityRuntimeID: 300, Data: 1.5}
V859 = bytes.fromhex("02ac020000c03f")

# generated by gophertunnel 324ed88:
# packet.Animate{ActionType: packet.AnimateActionRowLeft, EntityRuntimeID: 300, Data: 1.5, RowingTime: 2.5}
V859_ROWING = bytes.fromhex("8202ac020000c03f00002040")

GOLDENS = [
    pytest.param(
        v898.AnimatePacket(
            action=v898.AnimatePacket.Action.SWING,
            runtime_id=300,
            data=1.5,
            swing_source=v898.ActorSwingSource.ATTACK,
        ),
        SWING_ATTACK,
        id="v898-swing-attack",
    ),
    pytest.param(
        v898.AnimatePacket(action=v898.AnimatePacket.Action.CRITICAL_HIT, runtime_id=7, swing_source=None),
        WITHOUT_SWING_SOURCE,
        id="v898-without-swing-source",
    ),
    pytest.param(
        v898.AnimatePacket(
            action=v898.AnimatePacket.Action.NO_ACTION,
            runtime_id=1 << 32,
            swing_source=v898.ActorSwingSource.NONE,
        ),
        NONE_SWING_SOURCE,
        id="v898-none-swing-source",
    ),
    pytest.param(
        v898.AnimatePacket(
            action=v898.AnimatePacket.Action.MAGIC_CRITICAL_HIT,
            runtime_id=1,
            data=-1.0,
            swing_source=v898.ActorSwingSource.USE_ITEM,
        ),
        USE_ITEM_SWING_SOURCE,
        id="v898-use-item-swing-source",
    ),
    pytest.param(v844.AnimatePacket(action=1, runtime_id=300), V844, id="v844-swing"),
    pytest.param(v844.AnimatePacket(action=0x81, runtime_id=300, data=1.5), V844_ROWING, id="v844-rowing"),
    pytest.param(v859.AnimatePacket(action=1, runtime_id=300, data=1.5), V859, id="v859-swing"),
    pytest.param(
        v859.AnimatePacket(action=0x81, runtime_id=300, data=1.5, rowing_time=2.5),
        V859_ROWING,
        id="v859-rowing",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_animate_is_packet_44(version):
    assert version.PACKETS[44] is version.AnimatePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_animate_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_animate_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("packet", "golden"),
    [
        pytest.param(v844.AnimatePacket(action=1, runtime_id=300, data=1.5), V844, id="v844-data"),
        pytest.param(
            v859.AnimatePacket(action=1, runtime_id=300, data=1.5, rowing_time=2.5),
            V859,
            id="v859-rowing-time",
        ),
    ],
)
def test_animate_leaves_out_the_float_behind_an_unset_rowing_bit(packet, golden):
    assert bytes(packet) == golden


@pytest.fixture
def swing_attack_2225():
    return v2225.AnimatePacket(
        action=v2225.AnimatePacket.Action.SWING,
        runtime_id=300,
        data=1.5,
        swing_source=v2225.ActorSwingSource.ATTACK,
        hand=v2225.HandSlot.MAINHAND,
    )


def test_2225_appends_the_hand_after_the_898_body(swing_attack_2225):
    assert bytes(swing_attack_2225)[:-1] == SWING_ATTACK


def test_2225_adds_one_byte_for_the_hand(swing_attack_2225):
    assert len(bytes(swing_attack_2225)) == len(SWING_ATTACK) + 1


def test_2225_swinging_hand_changes_only_its_own_byte(swing_attack_2225):
    offhand = copy.copy(swing_attack_2225)
    offhand.hand = v2225.HandSlot.OFFHAND
    assert bytes(offhand)[:-1] == bytes(swing_attack_2225)[:-1]
    assert bytes(offhand) != bytes(swing_attack_2225)


def test_2225_offhand_round_trips():
    packet = v2225.AnimatePacket(action=v2225.AnimatePacket.Action.SWING, hand=v2225.HandSlot.OFFHAND)
    assert v2225.AnimatePacket.from_bytes(bytes(packet)) == packet
